// Learn Dutch with Kim site JS (migrated from Slater project 15512 on 2026-10-13).
// Source order: general (every page), then about (gated by path, as the Slater loader did).

// This file was generated by Slater.app - general.js


(function () {
  'use strict';

  // ===== CONFIGURATION =====
  const CONFIG = {
    gsap: {
      triggerStart: "top 88%",
      playOnce: "play none none none",
      eases: {
        custom1: "0.625, 0.05, 0, 1",
        rotation: "0.68, -0.55, 0.265, 1.55"
      }
    },
    swiper: {
      defaultSpeed: 700,
      dragSpeed: 250,
      dragEndDelay: 300
    }
  };

  // ===== STATE MANAGEMENT =====
  const state = {
    initialized: {
      swiper: new Set(),
      accordion: new Set(),
      youtubeEmbed: new Set()
    },
    gsapRegistered: false
  };

  // ===== UTILITY FUNCTIONS =====
  const utils = {
    /**
     * Safely query DOM elements
     */
    $(selector, parent = document) {
      return parent.querySelector(selector);
    },

    $$(selector, parent = document) {
      return Array.from(parent.querySelectorAll(selector));
    },

    /**
     * Check if library is loaded
     */
    isLoaded(library) {
      return typeof window[library] !== 'undefined';
    },

    /**
     * Debounce function for performance
     */
    debounce(func, wait) {
      let timeout;
      return function executedFunction(...args) {
        const later = () => {
          clearTimeout(timeout);
          func(...args);
        };
        clearTimeout(timeout);
        timeout = setTimeout(later, wait);
      };
    },

    /**
     * Parse attribute with fallback
     */
    parseAttr(element, attr, fallback, type = 'string') {
      const value = element.getAttribute(attr);
      if (value === null) return fallback;

      switch (type) {
      case 'boolean':
        return value === 'true';
      case 'number':
        return parseInt(value) || fallback;
      case 'float':
        return parseFloat(value) || fallback;
      default:
        return value || fallback;
      }
    }
  };

  // ===== MODULE: SWIPER =====
  const SwiperModule = {
    init() {
      if (!utils.isLoaded('Swiper')) {
        console.warn('Swiper library not loaded');
        return;
      }

      utils.$$('[mf-swiper="swiper"]').forEach(element => {
        if (state.initialized.swiper.has(element)) return;

        try {
          this.initializeSwiper(element);
          state.initialized.swiper.add(element);
        } catch (error) {
          console.error('Error initializing Swiper:', error);
        }
      });
    },

    initializeSwiper(element) {
      const config = this.parseConfig(element);
      const { nextEl, prevEl, paginationEl } = this.getNavigationElements(element, config);

      const swiper = new Swiper(utils.$('.swiper', element), {
        ...this.buildSwiperConfig(config, { nextEl, prevEl, paginationEl }),
        on: this.createEventHandlers(config)
      });

      this.setupYouTubeEmbeds(element, swiper, config);
      this.setupNavigation(swiper, { nextEl, prevEl }, config);
      this.setupPagination(swiper, paginationEl, config);
      this.setupResizeHandler(swiper, config);

      element.dispatchEvent(new CustomEvent('swiper:initialized', { detail: { swiper } }));
    },

    parseConfig(element) {
      const p = (attr, fallback, type) => utils.parseAttr(element, `mf-swiper-${attr}`,
        fallback, type);

      return {
        // Basic
        effect: p('effect', 'slide'),
        loop: p('loop', false, 'boolean'),
        direction: p('direction', 'horizontal'),
        speed: p('speed', CONFIG.swiper.defaultSpeed, 'number'),
        initialSlide: p('initial-slide', 0, 'number'),

        // Interaction
        grabCursor: p('grab-cursor', false, 'boolean'),
        keyboard: p('keyboard', false, 'boolean'),
        freeMode: p('free-mode', false, 'boolean'),
        disableDrag: p('disable-drag', false, 'boolean'),
        disableMousewheel: p('disable-mousewheel', false, 'boolean'),

        // Layout
        centeredSlides: p('centered-slides', false, 'boolean'),
        spaceBetween: p('space-between', 20, 'number'),

        // Effects
        crossFade: p('fade-crossfade', false, 'boolean'),
        lazy: p('lazy', false, 'boolean'),

        // Autoplay
        autoplay: p('autoplay', false, 'boolean'),
        autoplayDelay: p('autoplay-delay', 3000, 'number'),
        autoplayDisableOnInteraction: p('autoplay-disable-on-interaction', false, 'boolean'),

        // Pagination
        pagination: p('pagination', false, 'boolean'),
        paginationEl: p('pagination-el', ''),
        paginationClickable: p('pagination-clickable', false, 'boolean'),
        paginationType: p('pagination-type', 'bullets'),
        paginationDynamicBullets: p('pagination-dynamic-bullets', false, 'boolean'),
        paginationBulletClass: p('pagination-bullet-class', 'swiper_bullet'),
        paginationBulletActiveClass: p('pagination-bullet-active-class',
          'swiper_bullet-active'),

        // Navigation
        navigationNextEl: p('navigation-next-el', ''),
        navigationPrevEl: p('navigation-prev-el', ''),
        navigationDisabledClass: p('navigation-disabled-class', 'swiper_button-disabled'),

        // Thumbs
        thumbs: p('thumbs', ''),

        // Responsive
        mobileSlidesPerView: p('mobile-slides-per-view', 1, 'float'),
        mobileSpaceBetween: p('mobile-space-between', 10, 'number'),
        tabletSlidesPerView: p('tablet-slides-per-view', 2, 'float'),
        tabletSpaceBetween: p('tablet-space-between', 15, 'number'),
        desktopSlidesPerView: p('desktop-slides-per-view', 3, 'float'),
        desktopSpaceBetween: p('desktop-space-between', 20, 'number')
      };
    },

    getNavigationElements(element, config) {
      return {
        nextEl: config.navigationNextEl ? utils.$(`.${config.navigationNextEl}`, element) :
          null,
        prevEl: config.navigationPrevEl ? utils.$(`.${config.navigationPrevEl}`, element) :
          null,
        paginationEl: config.pagination ? utils.$(`.${config.paginationEl}`, element) : null
      };
    },

    buildSwiperConfig(config, elements) {
      return {
        // Core
        loop: config.loop,
        direction: config.direction,
        speed: config.speed,
        initialSlide: config.initialSlide,
        effect: config.effect,
        grabCursor: config.grabCursor,
        centeredSlides: config.centeredSlides,
        spaceBetween: config.spaceBetween,
        slideToClickedSlide: false,
        preventClicks: true,
        preventClicksPropagation: true,
        threshold: 5,
        allowTouchMove: !config.disableDrag,

        // Effects
        fadeEffect: config.effect === 'fade' ? { crossFade: config.crossFade } : {},

        // Features
        keyboard: config.keyboard ? { enabled: true } : false,
        freeMode: config.freeMode ? { enabled: true, sticky: true } : false,
        lazy: config.lazy ? { loadPrevNext: true, loadPrevNextAmount: 2 } : false,
        autoplay: config.autoplay ? {
          delay: config.autoplayDelay,
          disableOnInteraction: config.autoplayDisableOnInteraction
        } : false,

        // Navigation
        pagination: elements.paginationEl ? {
          el: elements.paginationEl,
          clickable: config.paginationClickable,
          type: config.paginationType,
          dynamicBullets: config.paginationDynamicBullets,
          bulletClass: config.paginationBulletClass,
          bulletActiveClass: config.paginationBulletActiveClass
        } : false,
        navigation: {
          nextEl: elements.nextEl,
          prevEl: elements.prevEl,
          disabledClass: config.navigationDisabledClass
        },

        // Mousewheel
        mousewheel: !config.disableMousewheel ? {
          forceToAxis: true,
          thresholdDelta: 5,
          releaseOnEdges: true
        } : false,

        // Thumbs
        thumbs: config.thumbs ? {
          swiper: utils.$(`.${config.thumbs}`)
        } : undefined,

        // Responsive
        breakpoints: {
          0: {
            slidesPerView: config.mobileSlidesPerView,
            spaceBetween: config.mobileSpaceBetween
          },
          767: {
            slidesPerView: config.tabletSlidesPerView,
            spaceBetween: config.tabletSpaceBetween
          },
          988: {
            slidesPerView: config.desktopSlidesPerView,
            spaceBetween: config.desktopSpaceBetween
          }
        }
      };
    },

    createEventHandlers(config) {
      return {
        touchStart: function () {
          this.wrapperEl.classList.add('swiper-dragging');
          this.params.speed = CONFIG.swiper.dragSpeed;
        },
        touchEnd: function () {
          setTimeout(() => {
            this.params.speed = config.speed;
            this.wrapperEl.classList.remove('swiper-dragging');
          }, CONFIG.swiper.dragEndDelay);
        }
      };
    },

    setupYouTubeEmbeds(element, swiper, config) {
      utils.$$('.video-youtube-embed', element).forEach(embed => {
        const handler = (e) => {
          e.stopImmediatePropagation();
          swiper.allowClick = false;
          swiper.allowTouchMove = false;
          setTimeout(() => {
            swiper.allowClick = true;
            swiper.allowTouchMove = !config.disableDrag;
          }, 100);
        };

        embed.addEventListener('mousedown', handler, true);
        embed.addEventListener('touchstart', handler, true);
      });
    },

    setupNavigation(swiper, { nextEl, prevEl }, config) {
      if (!config.loop || !nextEl || !prevEl) return;

      const isTabletOrSmaller = () => window.innerWidth <= 991;

      const handleNavClick = (direction) => (e) => {
        e.preventDefault();
        e.stopPropagation();

        if (!isTabletOrSmaller()) {
          swiper.params.speed = 0;
          swiper[direction === 'next' ? 'slideNext' : 'slidePrev']();
          setTimeout(() => {
            swiper.params.speed = config.speed;
          }, 50);
        } else {
          swiper.params.speed = config.speed;
          swiper[direction === 'next' ? 'slideNext' : 'slidePrev']();
        }
      };

      nextEl.addEventListener('click', handleNavClick('next'), true);
      prevEl.addEventListener('click', handleNavClick('prev'), true);
    },

    setupPagination(swiper, paginationEl, config) {
      if (!paginationEl) return;

      paginationEl.addEventListener('click', () => {
        if (window.innerWidth <= 991) {
          swiper.params.speed = config.speed;
        }
      });
    },

    setupResizeHandler(swiper, config) {
      window.addEventListener('resize', utils.debounce(() => {
        swiper.params.speed = config.speed;
      }, 250));
    }
  };

  // ===== MODULE: ACCORDION =====
  const AccordionModule = {
    init() {
      utils.$$('.accordion-item').forEach((item, listIndex) => {
        const container = item.closest('[data-close-previous]') || item.parentElement;

        if (state.initialized.accordion.has(container)) return;
        state.initialized.accordion.add(container);

        this.initializeAccordion(container, listIndex);
      });
    },

    initializeAccordion(container, listIndex) {
      const config = this.parseConfig(container);
      const accordionState = {
        previousIndex: null,
        closeFunctions: []
      };

      utils.$$('.accordion-item', container).forEach((card, cardIndex) => {
        this.setupAccordionItem(card, cardIndex, listIndex, config, accordionState);
      });
    },

    parseConfig(container) {
      return {
        closePrevious: container.getAttribute('data-close-previous') !== 'false',
        closeOnSecondClick: container.getAttribute('data-close-on-second-click') !== 'false',
        openOnHover: container.getAttribute('data-open-on-hover') === 'true',
        openByDefault: container.hasAttribute('data-open-by-default') &&
          !isNaN(+container.getAttribute('data-open-by-default')) ?
          +container.getAttribute('data-open-by-default') : false
      };
    },

    setupAccordionItem(card, cardIndex, listIndex, config, state) {
      const elements = this.getAccordionElements(card);
      if (!elements) return;

      const { component, button, content, vLine } = elements;

      this.setupAria(button, content, listIndex, cardIndex);
      content.style.display = 'none';

      const animation = this.createAnimation(content, vLine);
      const { openAccordion, closeAccordion } = this.createHandlers(
        component, button, animation, config, state, cardIndex
      );

      state.closeFunctions[cardIndex] = closeAccordion;

      if (config.openByDefault === cardIndex) openAccordion(true);

      button.addEventListener('click', () => {
        if (component.classList.contains('is-opened') && config.closeOnSecondClick) {
          closeAccordion();
          state.previousIndex = null;
        } else {
          openAccordion();
        }
      });

      if (config.openOnHover) {
        button.addEventListener('mouseenter', () => openAccordion());
      }
    },

    getAccordionElements(card) {
      const component = utils.$('.accordion-component', card);
      if (!component) return null;

      const button = utils.$('.accordion-toggle-button', component);
      const content = utils.$('.accordion-content-wrap', component);
      const vLine = utils.$('.accordion-icon-live-v', component);

      if (!button || !content || !vLine) {
        console.warn('Missing accordion elements:', card);
        return null;
      }

      return { component, button, content, vLine };
    },

    setupAria(button, content, listIndex, cardIndex) {
      button.setAttribute('aria-expanded', 'false');
      button.setAttribute('id', `accordion_button_${listIndex}_${cardIndex}`);
      content.setAttribute('id', `accordion_content_${listIndex}_${cardIndex}`);
      button.setAttribute('aria-controls', content.id);
      content.setAttribute('aria-labelledby', button.id);
    },

    createAnimation(content, vLine) {
      if (!utils.isLoaded('gsap')) return null;

      const refresh = () => {
        animation.invalidate();
        if (utils.isLoaded('ScrollTrigger')) {
          ScrollTrigger.refresh();
        }
      };

      const animation = gsap.timeline({
        paused: true,
        defaults: { duration: 0.4, ease: 'back' },
        onComplete: refresh,
        onReverseComplete: refresh
      });

      animation
        .set(content, { display: 'block' })
        .fromTo(content, { height: 0 }, { height: 'auto' })
        .fromTo(vLine, { height: '100%' }, { height: 0 }, '<');

      return animation;
    },

    createHandlers(component, button, animation, config, state, cardIndex) {
      const closeAccordion = () => {
        if (component.classList.contains('is-opened')) {
          component.classList.remove('is-opened');
          button.setAttribute('aria-expanded', 'false');
          if (animation) animation.reverse();
        }
      };

      const openAccordion = (instant = false) => {
        if (config.closePrevious && state.previousIndex !== null && state.previousIndex !==
          cardIndex) {
          state.closeFunctions[state.previousIndex]?.();
        }

        state.previousIndex = cardIndex;
        button.setAttribute('aria-expanded', 'true');
        component.classList.add('is-opened');

        if (animation) {
          instant ? animation.progress(1) : animation.play();
        }
      };

      return { openAccordion, closeAccordion };
    }
  };

  // ===== MODULE: GSAP ANIMATIONS =====
  const GSAPAnimations = {
    init() {
      if (!utils.isLoaded('gsap') || !utils.isLoaded('ScrollTrigger')) {
        console.warn('GSAP or ScrollTrigger not loaded');
        return;
      }

      this.registerPlugins();
      this.setupAnimations();
    },

    registerPlugins() {
      if (state.gsapRegistered) return;

      gsap.registerPlugin(ScrollTrigger);

      if (utils.isLoaded('SplitText')) {
        gsap.registerPlugin(SplitText);
      }

      if (utils.isLoaded('CustomEase')) {
        gsap.registerPlugin(CustomEase);
        CustomEase.create("customEase1", CONFIG.gsap.eases.custom1);
        CustomEase.create("rotationEase", CONFIG.gsap.eases.rotation);
      }

      state.gsapRegistered = true;
    },

    setupAnimations() {
      this.initWordReveal();
      this.initGeneralAnimations();
      this.initSimpleAnimations();
      this.initRotationAnimations();
      this.initEyebrowAnimations();
      this.initHeroAnimations();
    },

    // Text animation helpers
    getTextAnimationValues(lineCount) {
      let stagger = 0.1;
      let duration = 0.6;

      if (lineCount >= 3) {
        stagger = Math.max(0.03, 0.1 - (lineCount - 2) * 0.01);
        duration = Math.min(0.9, 0.6 + (lineCount - 2) * 0.04);
      }

      return { stagger, duration };
    },

    wrapInMask(text, className = "eyebrow-text-mask") {
      if (text && !text.parentElement.classList.contains(className)) {
        const wrapper = document.createElement("div");
        wrapper.className = className;
        wrapper.style.overflow = "hidden";
        text.parentNode.insertBefore(wrapper, text);
        wrapper.appendChild(text);
      }
    },

    hasBlockChildren(element) {
      return element.children.length > 0 &&
        Array.from(element.children).some(child =>
          window.getComputedStyle(child).display === 'block'
        );
    },

    // Animation methods
    initWordReveal() {
      if (!utils.isLoaded('SplitText')) return;

      utils.$$("[data-word-reveal='true']").forEach(text => {
        const hasBlocks = this.hasBlockChildren(text);

        const tl = gsap.timeline({
          scrollTrigger: {
            trigger: text,
            start: CONFIG.gsap.triggerStart,
            toggleActions: CONFIG.gsap.playOnce,
          },
        });

        if (hasBlocks) {
          this.animateBlockText(text, tl);
        } else {
          this.animateInlineText(text, tl);
        }

        gsap.set(text, { visibility: "visible" });
      });
    },

    animateBlockText(text, timeline) {
      const groups = this.groupParagraphs(text);

      groups.forEach(group => {
        const split = SplitText.create(group, {
          type: "lines",
          linesClass: "line",
        });

        const { stagger, duration } = this.getTextAnimationValues(split.lines.length);

        timeline.from(split.lines, {
          yPercent: 70,
          opacity: 0,
          duration: duration,
          stagger: stagger,
          ease: "customEase1",
        }, 0.1);
      });
    },

    animateInlineText(text, timeline) {
      const split = SplitText.create(text, {
        type: "lines",
        linesClass: "line",
      });

      const { stagger, duration } = this.getTextAnimationValues(split.lines.length);

      timeline.from(split.lines, {
        yPercent: 70,
        opacity: 0,
        delay: 0.1,
        duration: duration,
        stagger: stagger,
        ease: "customEase1",
      });
    },

    groupParagraphs(text) {
      const groups = [];
      let currentGroup = [];

      Array.from(text.children).forEach((child, index) => {
        const isParagraph = child.tagName.toLowerCase() === 'p';
        const prevIsParagraph = index > 0 &&
          text.children[index - 1].tagName.toLowerCase() === 'p';

        if (isParagraph && (currentGroup.length === 0 || prevIsParagraph)) {
          currentGroup.push(child);
        } else {
          if (currentGroup.length > 0) {
            groups.push(currentGroup);
            currentGroup = [];
          }
          groups.push([child]);
          if (isParagraph) {
            currentGroup = [child];
          }
        }
      });

      if (currentGroup.length > 0) {
        groups.push(currentGroup);
      }

      return groups;
    },

    initGeneralAnimations() {
      gsap.set("[data-animate='true']", {
        opacity: 0,
        y: 40
      });

      ScrollTrigger.batch("[data-animate='true']", {
        onEnter: batch => {
          gsap.to(batch, {
            opacity: 1,
            y: 0,
            duration: 0.9,
            ease: "customEase1",
            stagger: 0.12,
            overwrite: 'auto'
          });
        },
        start: CONFIG.gsap.triggerStart,
        once: true
      });
    },

    initSimpleAnimations() {
      gsap.set("[data-animate-simple='true']", { opacity: 0 });

      utils.$$("[data-animate-simple='true']").forEach(element => {
        const delay = parseFloat(element.dataset.delay) || 0;

        gsap.to(element, {
          opacity: 1,
          duration: 0.8,
          delay: delay,
          ease: "power2.out",
          scrollTrigger: {
            trigger: element,
            start: CONFIG.gsap.triggerStart,
            toggleActions: CONFIG.gsap.playOnce
          }
        });
      });
    },

    initRotationAnimations() {
      gsap.set("[data-animate-rotate='true']", {
        opacity: 0,
        rotateZ: -3.5,
        scale: 0.93
      });

      utils.$$("[data-animate-rotate='true']").forEach(element => {
        const delay = parseFloat(element.dataset.delay) || 0;

        gsap.timeline({
            scrollTrigger: {
              trigger: element,
              start: CONFIG.gsap.triggerStart,
              toggleActions: CONFIG.gsap.playOnce
            }
          })
          .to(element, {
            opacity: 1,
            duration: 0.6,
            ease: "power2.out"
          }, delay)
          .to(element, {
            rotateZ: 0,
            scale: 1,
            duration: 0.8,
            ease: "rotationEase"
          }, delay);
      });
    },

    initEyebrowAnimations() {
      utils.$$("[data-animate-eyebrow='true']").forEach(eyebrow => {
        const text = utils.$(".eyebrow-text", eyebrow);
        const background = utils.$(".background-color", eyebrow);

        this.wrapInMask(text);

        if (background) {
          gsap.set(background, {
            opacity: 0,
            scaleX: 0.1,
            scaleY: 0.85,
          });
        }

        if (text) {
          gsap.set(text, { yPercent: 110 });
        }

        const tl = gsap.timeline({
          scrollTrigger: {
            trigger: eyebrow,
            start: CONFIG.gsap.triggerStart,
            toggleActions: CONFIG.gsap.playOnce
          }
        });

        if (background) {
          tl.to(background, {
            opacity: 1,
            scaleX: 1,
            scaleY: 1,
            duration: 0.7,
            ease: "power2.out"
          });
        }

        if (text) {
          tl.to(text, {
            yPercent: 0,
            duration: 0.6,
            ease: "customEase1"
          }, "-=0.4");
        }
      });
    },

    initHeroAnimations() {
      utils.$$("[data-hero-section]").forEach(hero => {
        const elements = this.getHeroElements(hero);
        const masterTl = gsap.timeline({
          scrollTrigger: {
            trigger: hero,
            start: CONFIG.gsap.triggerStart,
            toggleActions: CONFIG.gsap.playOnce
          }
        });

        this.animateHeroSequence(masterTl, elements);
      });
    },

    getHeroElements(hero) {
      const eyebrowParent = utils.$("[data-hero-eyebrow]", hero);
      return {
        eyebrow: eyebrowParent ? utils.$(".eyebrow", eyebrowParent) : null,
        h1: utils.$("[data-hero-hero-h1]", hero),
        paragraph: utils.$("[data-hero-p]", hero),
        bgImage: utils.$("[data-hero-image-bg]", hero),
        bgShape: utils.$("[data-hero-std-image-main]", hero)
      };
    },

    animateHeroSequence(timeline, elements) {
      const { eyebrow, h1, paragraph, bgImage, bgShape } = elements;

      // 1. Eyebrow
      if (eyebrow) {
        this.animateHeroEyebrow(timeline, eyebrow);
      }

      // 2. H1
      if (h1 && utils.isLoaded('SplitText')) {
        this.animateHeroText(timeline, h1, "-=0.5");
      }

      // 3. Paragraph
      if (paragraph && utils.isLoaded('SplitText')) {
        this.animateHeroText(timeline, paragraph, "-=0.4");
      }

      // 4. Background Image
      if (bgImage) {
        this.animateHeroBackground(timeline, bgImage, "-=0.3");
      }

      // 5. Background Shape
      if (bgShape) {
        this.animateHeroBackground(timeline, bgShape, "-=0.7");
      }
    },

    animateHeroEyebrow(timeline, eyebrow) {
      const eyebrowText = utils.$(".eyebrow-text", eyebrow);
      const eyebrowBg = utils.$(".background-color", eyebrow);

      this.wrapInMask(eyebrowText);

      if (eyebrowBg) {
        gsap.set(eyebrowBg, { opacity: 0, scaleX: 0, scaleY: 0.85 });
        timeline.to(eyebrowBg, {
          opacity: 1,
          scaleX: 1,
          scaleY: 1,
          duration: 0.7,
          ease: "power2.out"
        });
      }

      if (eyebrowText) {
        gsap.set(eyebrowText, { yPercent: 110 });
        timeline.to(eyebrowText, {
          yPercent: 0,
          duration: 0.6,
          ease: "customEase1"
        }, "-=0.5");
      }
    },

    animateHeroText(timeline, element, position) {
      const split = SplitText.create(element, {
        type: "lines",
        linesClass: "line"
      });

      const { stagger, duration } = this.getTextAnimationValues(split.lines.length);

      gsap.set(element, { visibility: "visible" });

      timeline.from(split.lines, {
        yPercent: 70,
        opacity: 0,
        duration: duration,
        stagger: stagger,
        ease: "customEase1"
      }, position);
    },

    animateHeroBackground(timeline, element, position) {
      gsap.set(element, {
        opacity: 0,
        rotateZ: -3.5,
        scale: 0.93
      });

      timeline
        .to(element, {
          opacity: 1,
          duration: 0.6,
          ease: "power2.out"
        }, position)
        .to(element, {
          rotateZ: 0,
          scale: 1,
          duration: 0.8,
          ease: "rotationEase"
        }, "<");
    }
  };

  // ===== MODULE: YOUTUBE EMBED =====
  const YouTubeModule = {
    preconnected: false,

    init() {
      this.initializeEmbeds();

      // Re-initialize on Webflow load
      window.Webflow = window.Webflow || [];
      window.Webflow.push(() => this.initializeEmbeds());

      // Expose class globally if needed
      window.WebflowYouTubeEmbed = this.YouTubeEmbed;
    },

    initializeEmbeds() {
      utils.$$('.video-youtube-embed[data-youtube-url]').forEach(embed => {
        if (!state.initialized.youtubeEmbed.has(embed)) {
          new this.YouTubeEmbed(embed);
          state.initialized.youtubeEmbed.add(embed);
        }
      });
    },

    YouTubeEmbed: class {
      constructor(element) {
        this.element = element;
        this.youtubeUrl = element.dataset.youtubeUrl;
        this.videoId = this.extractVideoId(this.youtubeUrl);
        this.thumbnail = utils.$('.video-youtube-thumbnail', element);
        this.playButton = utils.$('.video-youtube-play-button', element);
        this.isActivated = false;

        if (this.videoId) this.init();
      }

      extractVideoId(url) {
        const patterns = [
          /(?:youtube\.com\/watch\?v=|youtube\.com\/embed\/|youtube\.com\/v\/)([\w-]{11})/,
          /youtu\.be\/([\w-]{11})/,
          /youtube\.com\/shorts\/([\w-]{11})/
        ];

        for (const pattern of patterns) {
          const match = url.match(pattern);
          if (match) return match[1];
        }

        return /^[\w-]{11}$/.test(url) ? url : null;
      }

      init() {
        this.loadThumbnail();
        this.setupPlayButton();
        this.element.addEventListener('pointerover', () => this
          .warmConnections(), { once: true });
        this.element.addEventListener('click', (e) => this.handleClick(e));
        this.element.addEventListener('keydown', (e) => this.handleKeydown(e));
      }

      setupPlayButton() {
        if (!this.playButton) return;

        this.playButton.setAttribute('role', 'button');
        this.playButton.setAttribute('aria-label', 'Play video');
        this.playButton.setAttribute('tabindex', '0');
      }

      loadThumbnail() {
        if (!this.thumbnail) return;

        const qualities = ['maxresdefault', 'hqdefault', 'mqdefault', 'default'];
        let qualityIndex = 0;

        const tryLoad = () => {
          if (qualityIndex >= qualities.length) return;

          const url =
            `https://i.ytimg.com/vi/${this.videoId}/${qualities[qualityIndex]}.jpg`;
          const img = new Image();

          img.onload = () => this.thumbnail.src = url;
          img.onerror = () => {
            qualityIndex++;
            tryLoad();
          };

          img.src = url;
        };

        tryLoad();
      }

      warmConnections() {
        if (YouTubeModule.preconnected) return;

        const urls = [
          'https://www.youtube-nocookie.com',
          'https://www.google.com',
          'https://googleads.g.doubleclick.net',
          'https://static.doubleclick.net'
        ];

        urls.forEach(href => {
          const link = document.createElement('link');
          link.rel = 'preconnect';
          link.href = href;
          document.head.appendChild(link);
        });

        YouTubeModule.preconnected = true;
      }

      handleClick(e) {
        if (e.target.tagName === 'A') return;
        e.preventDefault();
        this.activate();
      }

      handleKeydown(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          this.activate();
        }
      }

      activate() {
        if (this.isActivated) return;

        this.isActivated = true;
        this.element.classList.add('is-activated');

        const iframe = document.createElement('iframe');
        iframe.className = 'video-youtube-iframe';
        iframe.allow =
          'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
        iframe.allowFullscreen = true;
        iframe.title = 'YouTube video player';
        iframe.src =
          `https://www.youtube-nocookie.com/embed/${this.videoId}?autoplay=1&playsinline=1&rel=0&modestbranding=1`;

        this.element.appendChild(iframe);
        iframe.focus();
      }
    }
  };

  // ===== MODULE: MISC FEATURES =====
  const MiscFeatures = {
    init() {
      this.initButtonAnimation();
      this.initHideIfEmpty();
      this.initCustomFormSubmit();
      this.initDraggableStickers();
    },

    initButtonAnimation() {
      const offsetIncrement = 0.005;

      utils.$$('[data-button-animate-chars]').forEach(button => {
        const text = button.textContent;
        button.innerHTML = '';

        [...text].forEach((char, index) => {
          const span = document.createElement('span');
          span.textContent = char;
          span.style.transitionDelay = `${index * offsetIncrement}s`;

          if (char === ' ') {
            span.style.whiteSpace = 'pre';
          }

          button.appendChild(span);
        });
      });
    },

    initHideIfEmpty() {
      const isEffectivelyEmpty = (el) => {
        const visible = Array.from(el.querySelectorAll(':not(.w-condition-invisible)'))
          .some(child => {
            const rect = child.getBoundingClientRect();
            return rect.width > 0 && rect.height > 0;
          });
        return !visible;
      };

      utils.$$('[data-hide-if-empty], .u-hide-if-empty').forEach(el => {
        if (isEffectivelyEmpty(el)) {
          el.style.display = 'none';
        }
      });
    },

    initCustomFormSubmit() {
      utils.$$('[mf-code-submit-new]').forEach(button => {
        button.addEventListener('click', function (e) {
          e.preventDefault();

          const submitId = this.getAttribute('mf-code-submit-new');
          const oldSubmitButton = utils.$(`[mf-code-submit-old="${submitId}"]`);

          if (oldSubmitButton) {
            oldSubmitButton.click();
          } else {
            console.error(`No matching old submit button found for ID: ${submitId}`);
          }
        });
      });
    },

    initDraggableStickers() {
      if (!utils.isLoaded('gsap') || !utils.isLoaded('Draggable')) return;

      gsap.registerPlugin(Draggable);

      const wrapper = utils.$('[data-sticker="wrap"]');
      const stickers = utils.$$('[data-sticker="item"]');

      if (!wrapper || !stickers.length) return;

      stickers.forEach(sticker => {
        Draggable.create(sticker, {
          bounds: wrapper,
          dragResistance: 0.1,
          onPress() {
            gsap.to(this.target, {
              scale: 1.12,
              rotation: gsap.utils.random(-15, 15),
              filter: "drop-shadow(0px 10px 12px rgba(0,0,0,0.3))",
              duration: 0.1
            });
          },
          onRelease() {
            gsap.to(this.target, {
              scale: 1,
              rotation: 0,
              ease: "back.out(3)",
              filter: "drop-shadow(0px 0px 0px rgba(0,0,0,0))",
              duration: 0.2
            });
          }
        });
      });
    }
  };

  // ===== INITIALIZATION =====
  const App = {
    init() {
      // Core modules
      SwiperModule.init();
      AccordionModule.init();
      YouTubeModule.init();
      MiscFeatures.init();

      // GSAP animations (run after other modules)
      if (utils.isLoaded('gsap')) {
        // Small delay to ensure DOM is ready
        requestAnimationFrame(() => {
          GSAPAnimations.init();
        });
      }
    },

    // Public API for external access
    modules: {
      swiper: SwiperModule,
      accordion: AccordionModule,
      gsap: GSAPAnimations,
      youtube: YouTubeModule,
      misc: MiscFeatures
    },

    // Utility functions exposed
    utils: utils,

    // Re-initialize specific modules
    reinit(moduleName) {
      if (this.modules[moduleName]) {
        this.modules[moduleName].init();
      }
    }
  };

  App.init();

  // Expose to global scope if needed
  window.WebflowApp = App;

})();



